    def build_metadata(table_name: str) -> dict:
        """Return the static ``read_table_metadata`` dict for a table."""
        cfg = TABLE_CONFIG[table_name]
        ingestion_type = cfg.get("ingestion_type", "snapshot")
        metadata: dict = {
            "primary_keys": list(cfg.get("primary_keys", ["id"])),
            "ingestion_type": ingestion_type,
        }
        if ingestion_type != "snapshot":
            metadata["cursor_field"] = cfg.get("cursor_field", "update_time")
        return metadata


    ########################################################
    # src/databricks/labs/community_connector/sources/pipedrive/pipedrive_utils.py
    ########################################################

    DEFAULT_BASE_URL = "https://api.pipedrive.com"
    DEFAULT_START_DATE = "2010-01-01T00:00:00Z"
    REQUEST_TIMEOUT_SECONDS = 60
    MAX_RETRIES = 6
    INITIAL_BACKOFF_SECONDS = 2.0
    MAX_BACKOFF_SECONDS = 60.0
    RETRIABLE_STATUS_CODES = frozenset({429, 500, 502, 503, 504})

    # Pipedrive's burst limit is a rolling 2-second window per token.  The lowest
    # plan (Lite, API token) allows 20 requests / 2 s; the plan is not knowable
    # from config, so default to that floor (same as Airbyte).
    BURST_WINDOW_SECONDS = 2.0
    DEFAULT_BURST_LIMIT = 20

    # Status codes that mean "this company has no access to the feature" for the
    # optional Projects add-on tables (projects, tasks).
    OPTIONAL_TABLE_SKIP_CODES = frozenset({402, 403, 415})

    # Status codes for a deal that vanished / became hidden between the parent
    # deals read and the per-deal flow read.
    CHILD_SKIP_CODES = frozenset({403, 404, 410})

    _HEX40_RE = re.compile(r"^[0-9a-f]{40}$")
    _CANONICAL_FMT = "%Y-%m-%dT%H:%M:%SZ"


    class PipedriveAPIError(RuntimeError):
        """Raised for non-retriable / exhausted Pipedrive API errors."""

        def __init__(self, message: str, status_code: Optional[int] = None, is_json: bool = True):
            super().__init__(message)
            self.status_code = status_code
            self.is_json = is_json


    # --------------------------------------------------------------------------- #
    # Timestamps
    # --------------------------------------------------------------------------- #


    def parse_ts(value: Any) -> Optional[datetime]:
        """Parse any Pipedrive timestamp format into an aware UTC datetime.

        Handles RFC 3339 (``2025-01-01T10:20:00Z``, with or without fractional
        seconds / offsets) and v1's ``YYYY-MM-DD HH:MM:SS`` (UTC).  Returns
        ``None`` for empty or unparseable values.
        """
        if value is None or value == "":
            return None
        if isinstance(value, datetime):
            dt = value
        else:
            text = str(value).strip()
            if text.endswith("Z"):
                text = text[:-1] + "+00:00"
            try:
                dt = datetime.fromisoformat(text)
            except ValueError:
                try:
                    dt = datetime.strptime(text[:19], "%Y-%m-%d %H:%M:%S")
                except ValueError:
                    return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)


    def format_ts(dt: datetime) -> str:
        """Render a datetime in the canonical cursor form ``YYYY-MM-DDTHH:MM:SSZ``."""
        return dt.astimezone(timezone.utc).strftime(_CANONICAL_FMT)


    def normalize_ts(value: Any) -> Optional[str]:
        """Canonicalise a timestamp string (second precision, UTC, ``Z`` suffix)."""
        dt = parse_ts(value)
        return format_ts(dt) if dt else None


    def shift_ts(value: str, seconds: int) -> str:
        """Shift a canonical timestamp by ``seconds`` (negative = earlier)."""
        dt = parse_ts(value)
        if dt is None:
            raise ValueError(f"Invalid timestamp: {value!r}")
        return format_ts(dt + timedelta(seconds=seconds))


    def now_utc() -> str:
        return format_ts(datetime.now(timezone.utc))


    def record_cursor(record: dict, cursor_field: str = "update_time") -> Optional[str]:
        """Canonical cursor of a record, falling back to ``add_time`` when null."""
        return normalize_ts(record.get(cursor_field)) or normalize_ts(record.get("add_time"))


    # --------------------------------------------------------------------------- #
    # Record normalisation
    # --------------------------------------------------------------------------- #


    def _to_json_string(value: Any) -> Optional[str]:
        if value is None:
            return None
        if isinstance(value, str):
            return value
        return json.dumps(value, ensure_ascii=False, sort_keys=True)


    def normalize_record(
        record: dict,
        *,
        json_fields: tuple = (),
        json_array_fields: tuple = (),
        lead_custom_fields: bool = False,
        field_table: bool = False,
        deal_flow: bool = False,
        fill_update_time: bool = False,
    ) -> dict:
        """Adjust a raw Pipedrive record so it fits the static schema.

        Only shape-level fixes are applied (mixed-type / free-form values are
        JSON-encoded, aliases are mapped); value types are otherwise left to the
        framework's schema coercion.
        """
        rec = dict(record)

        if lead_custom_fields:
            # Leads inherit deal custom fields as root-level 40-hex keys that are
            # only present when set.  Gather them into one JSON column.
            custom = {k: rec.pop(k) for k in list(rec) if _HEX40_RE.match(str(k))}
            existing = rec.get("custom_fields")
            if isinstance(existing, dict):
                custom = {**existing, **custom}
            rec["custom_fields"] = custom or None

        if "ims" in rec and rec.get("im") is None:
            # Persons: the spec schema says ``im``; the migration guide says ``ims``.
            rec["im"] = rec.pop("ims")

        if field_table:
            flag = rec.get("mandatory_flag")
            if isinstance(flag, bool):
                rec["mandatory_flag"] = "true" if flag else "false"
            elif flag is not None:
                rec["mandatory_flag"] = _to_json_string(flag)

        if deal_flow:
            flag = rec.get("is_bulk_update_flag")
            if flag is not None and not isinstance(flag, bool):
                rec["is_bulk_update_flag"] = str(flag).lower() in ("1", "true", "yes")

        for name in json_fields:
            if name in rec:
                value = rec[name]
                # An empty ``custom_fields`` object carries no information.
                if name == "custom_fields" and value in ({}, []):
                    value = None
                rec[name] = _to_json_string(value)

        for name in json_array_fields:
            value = rec.get(name)
            if isinstance(value, list):
                rec[name] = [_to_json_string(v) for v in value]
            elif value is not None:
                rec[name] = [_to_json_string(value)]

        if fill_update_time and not rec.get("update_time") and rec.get("add_time"):
            # Records never updated have a null update_time; fall back to add_time
            # so the CDC sequence column is always populated.
            rec["update_time"] = rec["add_time"]

        return rec


    # --------------------------------------------------------------------------- #
    # HTTP client
    # --------------------------------------------------------------------------- #


    class PipedriveClient:
        """Thin ``requests`` wrapper: auth header, throttling, retries, pagination."""

        def __init__(self, api_token: str, base_url: str, burst_limit: int = DEFAULT_BURST_LIMIT):
            self._api_token = api_token
            self._base_url = base_url.rstrip("/")
            self._burst_limit = max(1, int(burst_limit))
            self._session: Optional[requests.Session] = None
            self._recent_calls: list[float] = []

        # Sessions are created lazily so the connector stays picklable.
        def __getstate__(self):
            state = dict(self.__dict__)
            state["_session"] = None
            state["_recent_calls"] = []
            return state

        @property
        def session(self) -> requests.Session:
            if self._session is None:
                sess = requests.Session()
                sess.headers.update(
                    {
                        "x-api-token": self._api_token,
                        "Accept": "application/json",
                        "User-Agent": "lakeflow-community-connector-pipedrive",
                    }
                )
                self._session = sess
            return self._session

        def _throttle(self) -> None:
            now = time.monotonic()
            window_start = now - BURST_WINDOW_SECONDS
            self._recent_calls = [t for t in self._recent_calls if t > window_start]
            if len(self._recent_calls) >= self._burst_limit:
                sleep_for = self._recent_calls[0] - window_start
                if sleep_for > 0:
                    time.sleep(sleep_for)
            self._recent_calls.append(time.monotonic())

        @staticmethod
        def _retry_delay(resp: requests.Response, backoff: float) -> float:
            reset = resp.headers.get("x-ratelimit-reset") or resp.headers.get("Retry-After")
            if reset:
                try:
                    # x-ratelimit-reset is *relative* seconds until window reset.
                    return min(MAX_BACKOFF_SECONDS, max(0.5, float(reset)))
                except ValueError:
                    pass
            return backoff

        def get(self, path: str, params: Optional[dict] = None) -> requests.Response:
            """GET with throttling and retry on 429 / 5xx.  Returns the final response."""
            url = f"{self._base_url}{path}"
            backoff = INITIAL_BACKOFF_SECONDS
            resp = None
            for attempt in range(MAX_RETRIES):
                self._throttle()
                try:
                    resp = self.session.get(url, params=params, timeout=REQUEST_TIMEOUT_SECONDS)
                except (requests.ConnectionError, requests.Timeout):
                    if attempt == MAX_RETRIES - 1:
                        raise
                    time.sleep(backoff)
                    backoff = min(MAX_BACKOFF_SECONDS, backoff * 2)
                    continue
                if resp.status_code not in RETRIABLE_STATUS_CODES:
                    return resp
                if attempt < MAX_RETRIES - 1:
                    time.sleep(self._retry_delay(resp, backoff))
                    backoff = min(MAX_BACKOFF_SECONDS, backoff * 2)
            return resp

        def get_json(self, path: str, params: Optional[dict] = None) -> dict:
            """GET and decode the JSON body; raise ``PipedriveAPIError`` on errors."""
            resp = self.get(path, params)
            content_type = resp.headers.get("Content-Type", "")
            is_json = "json" in content_type.lower()
            if resp.status_code != 200:
                snippet = resp.text[:300] if is_json else f"<{content_type or 'non-JSON'} body>"
                raise PipedriveAPIError(
                    f"Pipedrive API GET {path} failed with HTTP {resp.status_code}: {snippet}",
                    status_code=resp.status_code,
                    is_json=is_json,
                )
            try:
                body = resp.json()
            except ValueError as exc:
                raise PipedriveAPIError(
                    f"Pipedrive API GET {path} returned a non-JSON body ({content_type})",
                    status_code=resp.status_code,
                    is_json=False,
                ) from exc
            if isinstance(body, dict) and body.get("success") is False:
                raise PipedriveAPIError(
                    f"Pipedrive API GET {path} returned success=false: "
                    f"{body.get('error') or body.get('error_info') or ''}",
                    status_code=resp.status_code,
                )
            return body if isinstance(body, dict) else {"data": body}

        # ------------------------------------------------------------------ #
        # Pagination
        # ------------------------------------------------------------------ #

        def iter_v2_pages(self, path: str, params: dict) -> Iterator[list]:
            """Yield each page's ``data`` list from a cursor-paginated v2 endpoint."""
            query = dict(params)
            while True:
                body = self.get_json(path, query)
                data = body.get("data") or []
                yield data if isinstance(data, list) else [data]
                next_cursor = (body.get("additional_data") or {}).get("next_cursor")
                if not next_cursor or not data:
                    return
                query["cursor"] = next_cursor

        def iter_v1_pages(self, path: str, params: dict) -> Iterator[list]:
            """Yield each page's ``data`` list from an offset-paginated v1 endpoint.

            Endpoints without a ``pagination`` block are treated as a single page.
            """
            query = dict(params)
            while True:
                body = self.get_json(path, query)
                data = body.get("data") or []
                yield data if isinstance(data, list) else [data]
                pagination = (body.get("additional_data") or {}).get("pagination") or {}
                if not pagination.get("more_items_in_collection") or not data:
                    return
                current_start = int(query.get("start", 0))
                next_start = pagination.get("next_start")
                if next_start is None:
                    next_start = current_start + len(data)
                if int(next_start) <= current_start:
                    return  # defensive: never loop on a non-advancing offset
                query["start"] = next_start


    ########################################################
    # src/databricks/labs/community_connector/sources/pipedrive/pipedrive.py
    ########################################################

    V2_PAGE_MAX = 500
    DEFAULT_MAX_RECORDS_PER_BATCH = 5000
    # v1 notes / leads: Airbyte applies a 1h lookback to guard against clock skew
    # and late-committed writes.  v2 tables default to none.
    DEFAULT_V1_LOOKBACK_SECONDS = 3600
    DEFAULT_V2_LOOKBACK_SECONDS = 0
    # deal_flow selects parent deals updated since (cursor - lookback); entries are
    # then filtered by their own log_time, so a generous lookback is cheap insurance.
    DEFAULT_DEAL_FLOW_LOOKBACK_SECONDS = 3600
    # Clock-skew margin for the final deal_flow /deals re-scan, which starts from
    # the moment the /deals/archived phase began.
    DEAL_FLOW_RESCAN_SKEW_SECONDS = 300
    DEAL_PRODUCTS_BATCH = 100  # /api/v2/deals/products accepts at most 100 deal_ids

    DEALS_LIVE_STATUSES = "open,won,lost"
    DEALS_DELETED_STATUS = "deleted"
    DEALS_ALL_STATUSES = "open,won,lost,deleted"
    PROJECT_ALL_STATUSES = "open,completed,canceled,deleted"


    class PipedriveLakeflowConnect(LakeflowConnect):
        """Lakeflow connector for Pipedrive (API v1 + v2)."""

        def __init__(self, options: dict[str, str]) -> None:
            super().__init__(options)
            api_token = options.get("api_token")
            if not api_token:
                raise ValueError("Pipedrive connector requires 'api_token' in options")

            company_domain = (options.get("company_domain") or "").strip()
            if company_domain:
                # Accept "mycompany", "mycompany.pipedrive.com" or a full URL.
                host = company_domain.split("://", 1)[-1].strip("/")
                if not host.endswith(".pipedrive.com"):
                    host = f"{host}.pipedrive.com"
                base_url = f"https://{host}"
            else:
                base_url = DEFAULT_BASE_URL

            start_date = options.get("start_date") or DEFAULT_START_DATE
            normalized_start = normalize_ts(start_date)
            if normalized_start is None:
                raise ValueError(f"Invalid 'start_date' {start_date!r}; expected RFC 3339")
            self._start_date = normalized_start

            burst_limit = int(options.get("burst_limit") or DEFAULT_BURST_LIMIT)
            self._client = PipedriveClient(api_token, base_url, burst_limit=burst_limit)

            # Upper bound for every incremental read in this trigger.  Data changed
            # after this instant is picked up by the next trigger (fresh instance).
            self._init_ts = now_utc()
            # Tables (and their delete streams) whose one-time lookback was applied.
            self._lookback_applied: set[str] = set()

        # ------------------------------------------------------------------ #
        # Interface: discovery / schema / metadata
        # ------------------------------------------------------------------ #

        def list_tables(self) -> list[str]:
            return list(SUPPORTED_TABLES)

        def get_table_schema(self, table_name: str, table_options: dict[str, str]) -> StructType:
            self._validate_table(table_name)
            return TABLE_SCHEMAS[table_name]

        def read_table_metadata(self, table_name: str, table_options: dict[str, str]) -> dict:
            self._validate_table(table_name)
            return build_metadata(table_name)

        # ------------------------------------------------------------------ #
        # Interface: reads
        # ------------------------------------------------------------------ #

        def read_table(
            self, table_name: str, start_offset: dict, table_options: dict[str, str]
        ) -> tuple[Iterator[dict], dict]:
            self._validate_table(table_name)
            table_options = table_options or {}
            kind = TABLE_CONFIG[table_name]["kind"]

            if kind == "v2_incremental":
                status = DEALS_LIVE_STATUSES if TABLE_CONFIG[table_name].get("deal_status") else None
                return self._read_v2_incremental(
                    table_name, start_offset, table_options, status=status, stream_key=table_name
                )
            if kind == "v1_incremental":
                return self._read_v1_incremental(table_name, start_offset, table_options)
            if kind == "deal_flow":
                return self._read_deal_flow(start_offset, table_options)
            if kind == "v2_snapshot":
                return self._read_v2_snapshot(table_name), {}
            if kind == "v1_snapshot":
                return self._read_v1_snapshot(table_name), {}
            if kind == "projects":
                return self._read_projects(), {}
            if kind == "deal_products":
                return self._read_deal_products(), {}
            raise ValueError(f"Unhandled table kind {kind!r} for '{table_name}'")

        def read_table_deletes(
            self, table_name: str, start_offset: dict, table_options: dict[str, str]
        ) -> tuple[Iterator[dict], dict]:
            """Soft-deleted deals (``status=deleted``, last 30 days) as delete tombstones.

            Pipedrive keeps deleted deals for 30 days with ``is_deleted=true`` and a
            bumped ``update_time``; ``status=deleted`` returns only those.  This is a
            separate stream with its own offset, read with the same incremental
            algorithm as ``read_table``.
            """
            self._validate_table(table_name)
            if TABLE_CONFIG[table_name].get("ingestion_type") != "cdc_with_deletes":
                raise ValueError(f"Table '{table_name}' does not support deleted records")
            return self._read_v2_incremental(
                table_name,
                start_offset,
                table_options or {},
                status=DEALS_DELETED_STATUS,
                stream_key=f"{table_name}::deletes",
            )

        # ------------------------------------------------------------------ #
        # Helpers
        # ------------------------------------------------------------------ #

        def _validate_table(self, table_name: str) -> None:
            if table_name not in TABLE_CONFIG:
                raise ValueError(
                    f"Table '{table_name}' is not supported. Supported tables: {SUPPORTED_TABLES}"
                )

        def _normalize(self, table_name: str, record: dict) -> dict:
            cfg = TABLE_CONFIG[table_name]
            return normalize_record(
                record,
                json_fields=JSON_STRING_FIELDS.get(table_name, ()),
                json_array_fields=JSON_STRING_ARRAY_FIELDS if table_name in FIELD_TABLES else (),
                lead_custom_fields=bool(cfg.get("lead_custom_fields")),
                field_table=table_name in FIELD_TABLES,
                deal_flow=table_name == "deal_flow",
                fill_update_time=cfg.get("ingestion_type") in ("cdc", "cdc_with_deletes"),
            )

        @staticmethod
        def _int_option(table_options: dict, name: str, default: int, minimum: int = 0) -> int:
            raw = table_options.get(name)
            if raw is None or raw == "":
                return default
            try:
                value = int(raw)
            except (TypeError, ValueError) as exc:
                raise ValueError(f"Table option '{name}' must be an integer, got {raw!r}") from exc
            return max(minimum, value)

        def _query_lower_bound(self, stream_key: str, since: str, lookback_seconds: int) -> str:
            """Apply the lookback once per stream per trigger (never to the stored cursor)."""
            if lookback_seconds <= 0 or stream_key in self._lookback_applied:
                return since
            self._lookback_applied.add(stream_key)
            return shift_ts(since, -lookback_seconds)

        def _resolve_since(self, start_offset: Optional[dict]) -> Optional[str]:
            """Starting cursor, or ``None`` if the stream already caught up to init time."""
            cursor = (start_offset or {}).get("cursor")
            if cursor and cursor >= self._init_ts:
                return None
            return cursor or self._start_date

        # ------------------------------------------------------------------ #
        # v2 incremental (deals, deals_archived, persons, organizations,
        # activities, products)
        # ------------------------------------------------------------------ #

        def _read_v2_incremental(
            self,
            table_name: str,
            start_offset: Optional[dict],
            table_options: dict,
            *,
            status: Optional[str],
            stream_key: str,
        ) -> tuple[Iterator[dict], dict]:
            cfg = TABLE_CONFIG[table_name]
            since = self._resolve_since(start_offset)
            if since is None:
                return iter([]), start_offset

            max_records = self._int_option(
                table_options, "max_records_per_batch", DEFAULT_MAX_RECORDS_PER_BATCH, minimum=1
            )
            page_size = min(
                V2_PAGE_MAX,
                self._int_option(table_options, "page_size", V2_PAGE_MAX, minimum=1),
                max_records,
            )
            lookback = self._int_option(table_options, "lookback_seconds", DEFAULT_V2_LOOKBACK_SECONDS)

            params = {
                "limit": page_size,
                "sort_by": "update_time",
                "sort_direction": "asc",
                "updated_since": self._query_lower_bound(stream_key, since, lookback),
            }
            if cfg.get("supports_until"):
                params["updated_until"] = self._init_ts
            if status:
                params["status"] = status
            include_fields = table_options.get("include_fields", cfg.get("default_include_fields"))
            if include_fields:
                params["include_fields"] = include_fields

            records: list[dict] = []
            last_cursor = since
            for page in self._client.iter_v2_pages(cfg["path"], params):
                reached_cap = False
                for raw in page:
                    rc = record_cursor(raw)
                    if rc is not None and rc > self._init_ts:
                        # Sorted ascending: everything after this is past the cap
                        # (only reachable where updated_until isn't supported).
                        reached_cap = True
                        break
                    records.append(self._normalize(table_name, raw))
                    if rc is not None and rc > last_cursor:
                        last_cursor = rc
                if reached_cap:
                    break
                # Stop at a page boundary once the batch is full - but only after
                # the cursor has moved past ``since``; otherwise a run of rows that
                # share one update_time would never advance the offset.
                if len(records) >= max_records and last_cursor > since:
                    break

            end_offset = {"cursor": last_cursor}
            if not records or (start_offset and start_offset == end_offset):
                return iter([]), start_offset if start_offset else end_offset
            return iter(records), end_offset

        # ------------------------------------------------------------------ #
        # v1 incremental (notes, leads)
        # ------------------------------------------------------------------ #

        def _read_v1_incremental(
            self, table_name: str, start_offset: Optional[dict], table_options: dict
        ) -> tuple[Iterator[dict], dict]:
            cfg = TABLE_CONFIG[table_name]
            since = self._resolve_since(start_offset)
            if since is None:
                return iter([]), start_offset

            page_size = min(
                cfg.get("page_max", 500),
                self._int_option(table_options, "page_size", cfg.get("page_max", 500), minimum=1),
            )
            lookback = self._int_option(table_options, "lookback_seconds", DEFAULT_V1_LOOKBACK_SECONDS)
            params = {
                "limit": page_size,
                "start": 0,
                # Immutable sort key: an edit mid-read can't move a row onto an
                # already-read offset page.
                "sort": "id ASC",
                "updated_since": self._query_lower_bound(table_name, since, lookback),
            }

            # The cursor is only safe once the whole id-sorted range is drained,
            # so read every page in one micro-batch.
            records: list[dict] = []
            last_cursor = since
            for page in self._client.iter_v1_pages(cfg["path"], params):
                for raw in page:
                    rc = record_cursor(raw)
                    if rc is not None and rc > self._init_ts:
                        continue  # changed after init: next trigger picks it up
                    records.append(self._normalize(table_name, raw))
                    if rc is not None and rc > last_cursor:
                        last_cursor = rc

            end_offset = {"cursor": last_cursor}
            if not records or (start_offset and start_offset == end_offset):
                return iter([]), start_offset if start_offset else end_offset
            return iter(records), end_offset

        # ------------------------------------------------------------------ #
        # Snapshots
        # ------------------------------------------------------------------ #

        def _read_v2_snapshot(self, table_name: str) -> Iterator[dict]:
            cfg = TABLE_CONFIG[table_name]
            try:
                for page in self._client.iter_v2_pages(cfg["path"], {"limit": V2_PAGE_MAX}):
                    for raw in page:
                        yield self._normalize(table_name, raw)
            except PipedriveAPIError as exc:
                if cfg.get("optional") and self._is_feature_unavailable(exc):
                    return
                raise

        def _read_v1_snapshot(self, table_name: str) -> Iterator[dict]:
            cfg = TABLE_CONFIG[table_name]
            params: dict = {}
            if cfg.get("paginated"):
                params = {"start": 0, "limit": cfg.get("page_max", 500)}
                if cfg.get("sort"):
                    params["sort"] = cfg["sort"]
            for page in self._client.iter_v1_pages(cfg["path"], params):
                for raw in page:
                    yield self._normalize(table_name, raw)

        def _read_projects(self) -> Iterator[dict]:
            """Union of /projects and /projects/archived (all statuses), deduped on id."""
            cfg = TABLE_CONFIG["projects"]
            seen: set = set()
            params = {"limit": V2_PAGE_MAX, "status": PROJECT_ALL_STATUSES}
            try:
                for path in cfg["paths"]:
                    for page in self._client.iter_v2_pages(path, params):
                        for raw in page:
                            rid = raw.get("id")
                            if rid in seen:
                                continue
                            seen.add(rid)
                            yield self._normalize("projects", raw)
            except PipedriveAPIError as exc:
                if self._is_feature_unavailable(exc):
                    return
                raise

        @staticmethod
        def _is_feature_unavailable(exc: PipedriveAPIError) -> bool:
            """Projects add-on missing: 402/403/415 JSON errors, or a JSON 404.

            An HTML 403 is a Cloudflare block and an HTML 404 is an unknown route;
            both are real failures.
            """
            if not exc.is_json:
                return False
            return exc.status_code in OPTIONAL_TABLE_SKIP_CODES or exc.status_code == 404

        # ------------------------------------------------------------------ #
        # Deal children
        # ------------------------------------------------------------------ #

        def _iter_deal_ids(self) -> list:
            """All (non-deleted) deal IDs from /deals and /deals/archived, deduped."""
            ids: dict = {}
            for path in DEAL_PARENT_PATHS:
                for page in self._client.iter_v2_pages(path, {"limit": V2_PAGE_MAX}):
                    for deal in page:
                        if deal.get("id") is not None:
                            ids[deal["id"]] = None
            return list(ids)

        def _read_deal_products(self) -> Iterator[dict]:
            deal_ids = self._iter_deal_ids()
            path = TABLE_CONFIG["deal_products"]["path"]
            for i in range(0, len(deal_ids), DEAL_PRODUCTS_BATCH):
                chunk = deal_ids[i : i + DEAL_PRODUCTS_BATCH]
                params = {"deal_ids": ",".join(str(d) for d in chunk), "limit": V2_PAGE_MAX}
                for page in self._client.iter_v2_pages(path, params):
                    for raw in page:
                        yield self._normalize("deal_products", raw)

        def _read_deal_flow(
            self, start_offset: Optional[dict], table_options: dict
        ) -> tuple[Iterator[dict], dict]:
            """Deal change log, read via parent-incremental deals.

            Each trigger covers the log-time window ``(cursor, until]`` where
            ``until`` is the init time.  Parent deals updated since
            ``cursor - lookback`` are walked in ascending ``update_time`` order in
            three phases: ``/deals``, ``/deals/archived``, then ``/deals`` again
            from the moment the archived phase began.  For each deal the flow
            entries inside the window are emitted.

            The parent query is deliberately *not* capped with ``updated_until``:
            the walk spans many micro-batches (one 40-token call per deal), and a
            deal edited or archived before the walk reaches it gets a fresh
            ``update_time`` past ``until``.  Uncapped, such a deal just moves
            further ahead in the sort (or into the not-yet-walked archived list)
            and is still visited; capped, its window entries would be lost for
            good.  The final ``/deals`` re-scan covers deals unarchived while the
            archived list was being walked.  Entry rows are bounded client-side by
            ``log_time <= until``.

            A deal can therefore be visited twice in one window (edited after it
            was processed).  Rows are immutable and keyed on ``id`` (``cdc``), so
            a re-emitted row is an idempotent upsert; within one micro-batch,
            repeated deals and entries are skipped outright.

            The window is split across micro-batches by deal
            (``max_records_per_batch`` is best-effort: a deal's flow is never
            split).  In-progress offsets carry the phase, the ``update_time`` of
            the next unprocessed deal and the re-scan start.
            """
            offset = start_offset or {}
            lookback = self._int_option(
                table_options, "lookback_seconds", DEFAULT_DEAL_FLOW_LOOKBACK_SECONDS
            )
            if offset.get("phase") is not None:
                lower = offset["cursor"]
                until = offset["until"]
                phase = int(offset["phase"])
                deal_since = offset["deal_since"]
                rescan_since = offset.get("rescan_since")
            else:
                lower = self._resolve_since(start_offset)
                if lower is None:
                    return iter([]), start_offset
                until = self._init_ts
                phase = 0
                deal_since = shift_ts(lower, -lookback) if lookback > 0 else lower
                rescan_since = None

            max_records = self._int_option(
                table_options, "max_records_per_batch", DEFAULT_MAX_RECORDS_PER_BATCH, minimum=1
            )
            records, stopped_at = self._walk_deal_flow_phase(
                DEAL_FLOW_PHASE_PATHS[phase], deal_since, (lower, until), max_records
            )

            end_offset = {"cursor": lower, "until": until}
            if stopped_at:
                end_offset.update(phase=phase, deal_since=stopped_at)
                if rescan_since:
                    end_offset["rescan_since"] = rescan_since
            elif phase == 0:
                # Deals unarchived from here on re-enter /deals with an
                # update_time at or after this instant; the final phase
                # re-scans /deals from it.
                end_offset.update(
                    phase=1,
                    deal_since=shift_ts(lower, -lookback) if lookback > 0 else lower,
                    rescan_since=shift_ts(now_utc(), -DEAL_FLOW_RESCAN_SKEW_SECONDS),
                )
            elif phase + 1 < len(DEAL_FLOW_PHASE_PATHS):
                end_offset.update(phase=phase + 1, deal_since=rescan_since or until)
            else:
                end_offset = {"cursor": until}

            if start_offset and start_offset == end_offset:
                return iter([]), start_offset
            return iter(records), end_offset

        def _walk_deal_flow_phase(
            self, path: str, deal_since: str, window: tuple[str, str], max_records: int
        ) -> tuple[list[dict], Optional[str]]:
            """Walk one parent list (uncapped) and collect window entries.

            Returns the entries and, if the batch filled up, the ``update_time`` of
            the next unprocessed deal (``None`` once the list is exhausted).
            """
            params = {
                "limit": V2_PAGE_MAX,
                "sort_by": "update_time",
                "sort_direction": "asc",
                "updated_since": deal_since,
                "status": DEALS_ALL_STATUSES,
            }
            records: list[dict] = []
            seen_deals: set = set()
            seen_entries: set = set()
            last_deal_ts: Optional[str] = None
            for page in self._client.iter_v2_pages(path, params):
                for deal in page:
                    deal_ts = record_cursor(deal) or deal_since
                    # Only stop between deals with different update_time values,
                    # so resuming from ``deal_since=deal_ts`` (inclusive) never
                    # skips a deal.
                    if len(records) >= max_records and last_deal_ts and deal_ts > last_deal_ts:
                        return records, deal_ts
                    last_deal_ts = deal_ts
                    if deal.get("id") in seen_deals:
                        continue  # moved ahead in the sort within this batch
                    seen_deals.add(deal.get("id"))
                    for entry in self._read_one_deal_flow(deal.get("id"), *window):
                        if entry.get("id") is None or entry["id"] not in seen_entries:
                            seen_entries.add(entry.get("id"))
                            records.append(entry)
            return records, None

        def _read_one_deal_flow(self, deal_id, lower: str, until: str) -> list[dict]:
            if deal_id is None:
                return []
            path = TABLE_CONFIG["deal_flow"]["path"].replace("{id}", str(deal_id))
            params = {"items": "dealChange", "all_changes": 1, "start": 0, "limit": 500}
            out: list[dict] = []
            try:
                for page in self._client.iter_v1_pages(path, params):
                    for item in page:
                        if not isinstance(item, dict):
                            continue
                        if item.get("object", "dealChange") != "dealChange":
                            continue
                        entry = item.get("data")
                        if not isinstance(entry, dict):
                            continue
                        log_ts = normalize_ts(entry.get("log_time")) or normalize_ts(
                            item.get("timestamp")
                        )
                        if log_ts is None or not lower < log_ts <= until:
                            continue
                        out.append(self._normalize("deal_flow", entry))
            except PipedriveAPIError as exc:
                # Deal deleted / hidden between the parent read and this call.
                if exc.status_code in CHILD_SKIP_CODES and exc.is_json:
                    return out
                raise
            return out


    ########################################################
    # src/databricks/labs/community_connector/sparkpds/lakeflow_datasource.py
    ########################################################

    LakeflowConnectImpl = PipedriveLakeflowConnect
    # Constant option or column names
    METADATA_TABLE = "_community_table_metadata"
    NAMESPACES_TABLE = "_community_namespaces"
    TABLES_TABLE = "_community_tables"
    VIRTUAL_TABLES = (METADATA_TABLE, NAMESPACES_TABLE, TABLES_TABLE)
    TABLE_NAME = "tableName"
    TABLE_NAME_LIST = "tableNameList"
    TABLE_CONFIGS = "tableConfigs"
    IS_DELETE_FLOW = "isDeleteFlow"
    NAMESPACE_PREFIX = "namespacePrefix"
    NAMESPACE = "namespace"


    def _decode_list_of_str_option(option_name: str, value: str | None) -> list[str] | None:
        """Decode and validate a JSON-encoded ``list[str]`` Spark option.

        Returns ``None`` if the option is absent; otherwise the parsed list.
        Raises ``ValueError`` with the offending value if the JSON is malformed
        or the decoded value is not a list of strings.
        """
        if value is None:
            return None
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError as e:
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded list[str]; "
                f"got non-JSON value: {value!r}"
            ) from e
        if not isinstance(decoded, list) or not all(isinstance(s, str) for s in decoded):
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded list[str]; "
                f"got: {decoded!r}"
            )
        return decoded


    def _decode_dict_option(option_name: str, value: str | None) -> dict:
        """Decode and validate a JSON-encoded ``dict`` Spark option."""
        if value is None:
            return {}
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError as e:
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded dict; "
                f"got non-JSON value: {value!r}"
            ) from e
        if not isinstance(decoded, dict):
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded dict; got: {decoded!r}"
            )
        return decoded


    # PySpark's DataSource API requires camelCase method names and inherits
    # semantics from the parent class, so per-method docstrings are redundant.
    # pylint: disable=invalid-name,missing-function-docstring
    class LakeflowStreamReader(SimpleDataSourceStreamReader, SupportsTriggerAvailableNow):
        """
        Implements a data source stream reader for Lakeflow Connect.
        Currently, only the simpleStreamReader is implemented, which uses a
        more generic protocol suitable for most data sources that support
        incremental loading.
        """

        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.lakeflow_connect = lakeflow_connect
            self.schema = schema

        def initialOffset(self):
            return {}

        def read(self, start: dict) -> (Iterator[tuple], dict):
            is_delete_flow = self.options.get(IS_DELETE_FLOW) == "true"
            # Strip delete flow options before passing to connector
            table_options = {
                k: v for k, v in self.options.items() if k != IS_DELETE_FLOW
            }

            if is_delete_flow:
                records, offset = self.lakeflow_connect.read_table_deletes(
                    self.options[TABLE_NAME], start, table_options
                )
            else:
                records, offset = self.lakeflow_connect.read_table(
                    self.options[TABLE_NAME], start, table_options
                )
            rows = map(lambda x: parse_value(x, self.schema), records)
            return rows, offset

        def readBetweenOffsets(self, start: dict, end: dict) -> Iterator[tuple]:
            # TODO: This does not ensure the records returned are identical across repeated calls.
            # For append-only tables, the data source must guarantee that reading from the same
            # start offset will always yield the same set of records.
            # For tables ingested as incremental CDC, it is only necessary that no new changes
            # are missed in the returned records.
            return self.read(start)[0]

        def prepareForTriggerAvailableNow(self) -> None:
            # No need to do anything special here. Everything is handled in the __init__ method.
            pass


    class LakeflowPartitionedStreamReader(DataSourceStreamReader, SupportsTriggerAvailableNow):
        """Proxy that bridges SupportsPartitionedStream to PySpark's DataSourceStreamReader.

        Used when a connector implements the SupportsPartitionedStream mixin to
        support partitioned streaming reads across Spark executors.
        """

        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.schema = schema
            self.lakeflow_connect = lakeflow_connect
            self.table_name = options[TABLE_NAME]
            self.table_options = {k: v for k, v in options.items() if k != IS_DELETE_FLOW}

        def initialOffset(self):
            return {}

        def getDefaultReadLimit(self):
            # Admission control is the connector's responsibility (e.g. via
            # window_days, max_records_per_batch), not the engine's.  Always
            # ask the engine for ReadAllAvailable.
            return ReadAllAvailable()

        def latestOffset(self, start: dict, limit) -> dict:
            # We declared ReadAllAvailable via getDefaultReadLimit; the engine
            # must respect it.  Anything else means admission-control expectations
            # we do not support — fail loudly rather than silently ignore.
            if not isinstance(limit, ReadAllAvailable):
                raise ValueError(
                    f"LakeflowPartitionedStreamReader only supports ReadAllAvailable; "
                    f"got {type(limit).__name__}. Micro-batch sizing must be controlled "
                    f"by the connector implementation (table_options), not the engine."
                )
            return self.lakeflow_connect.latest_offset(
                self.table_name, self.table_options, start
            )

        def partitions(self, start: dict, end: dict):
            partition_descs = self.lakeflow_connect.get_partitions(
                self.table_name, self.table_options, start, end
            )
            return [InputPartition(json.dumps(p)) for p in partition_descs]

        def read(self, partition: InputPartition):
            partition_desc = json.loads(partition.value)
            records = self.lakeflow_connect.read_partition(
                self.table_name, partition_desc, self.table_options
            )
            return map(lambda x: parse_value(x, self.schema), records)

        def prepareForTriggerAvailableNow(self) -> None:
            # No need to do anything special here. Everything is handled in the __init__ method.
            pass


    class LakeflowBatchReader(DataSourceReader):
        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.schema = schema
            self.lakeflow_connect = lakeflow_connect
            self.table_name = options[TABLE_NAME]
            self._supports_partition = isinstance(lakeflow_connect, SupportsPartition)

        def partitions(self):
            if self._supports_partition and self.table_name not in VIRTUAL_TABLES:
                try:
                    partition_descs = self.lakeflow_connect.get_partitions(
                        self.table_name, self.options
                    )
                    return [InputPartition(json.dumps(p)) for p in partition_descs]
                except Exception:
                    self._supports_partition = False
            return [InputPartition(None)]

        def read(self, partition):
            if self.table_name == METADATA_TABLE:
                records = self._read_table_metadata()
            elif self.table_name == NAMESPACES_TABLE:
                records = self._read_namespaces()
            elif self.table_name == TABLES_TABLE:
                records = self._read_tables()
            elif self._supports_partition and partition.value is not None:
                partition_desc = json.loads(partition.value)
                records = self.lakeflow_connect.read_partition(
                    self.table_name, partition_desc, self.options
                )
            else:
                records, _ = self.lakeflow_connect.read_table(self.table_name, None, self.options)
            return map(lambda x: parse_value(x, self.schema), records)

        def _read_table_metadata(self):
            table_names = _decode_list_of_str_option(
                TABLE_NAME_LIST, self.options.get(TABLE_NAME_LIST)
            ) or []
            table_configs = _decode_dict_option(
                TABLE_CONFIGS, self.options.get(TABLE_CONFIGS)
            )
            all_records = []
            # Preserve caller-supplied table order — caller controls it.
            for table in table_names:
                metadata = self.lakeflow_connect.read_table_metadata(
                    table, table_configs.get(table, {})
                )
                all_records.append({TABLE_NAME: table, **metadata})
            return all_records

        def _read_namespaces(self):
            # Connectors without SupportsNamespaces are flat — no rows.
            if not isinstance(self.lakeflow_connect, SupportsNamespaces):
                return []
            prefix = _decode_list_of_str_option(
                NAMESPACE_PREFIX, self.options.get(NAMESPACE_PREFIX)
            )
            namespaces = self.lakeflow_connect.list_namespaces(prefix)
            # Sort framework-side for deterministic output regardless of
            # connector iteration order.
            return [{"namespace": ns} for ns in sorted(namespaces)]

        def _read_tables(self):
            namespace_supplied = NAMESPACE in self.options
            if isinstance(self.lakeflow_connect, SupportsNamespaces):
                if not namespace_supplied:
                    raise ValueError(
                        f"option '{NAMESPACE}' is required when reading "
                        f"'{TABLES_TABLE}' against a connector that implements "
                        f"SupportsNamespaces. Pass a JSON-encoded list[str] "
                        f"(use '[]' for root-level tables; walk the tree via "
                        f"'{NAMESPACES_TABLE}' to enumerate every namespace)."
                    )
                namespace = _decode_list_of_str_option(
                    NAMESPACE, self.options[NAMESPACE]
                )
                tables = self.lakeflow_connect.list_tables_in_namespace(namespace)
                return [
                    {"namespace": namespace, TABLE_NAME: tn}
                    for tn in sorted(tables)
                ]
            # Flat connector path. Reject a stray `namespace` option — the
            # caller probably mistook this connector for namespace-aware and
            # silently ignoring the option would mask the bug.
            if namespace_supplied:
                raise ValueError(
                    f"option '{NAMESPACE}' was supplied but the connector does "
                    f"not implement SupportsNamespaces. Either omit the option "
                    f"or use a namespace-aware connector."
                )
            return [
                {"namespace": [], TABLE_NAME: tn}
                for tn in sorted(self.lakeflow_connect.list_tables())
            ]


    class LakeflowSource(DataSource):
        """
        PySpark DataSource base for Lakeflow Connect.

        Two ways the connector implementation is bound:

        - Per-source subclass (wheel / multi-file deployment): subclass and set
          ``_lakeflow_connect_cls``::

              class GmailDataSource(LakeflowSource):
                  _lakeflow_connect_cls = GmailLakeflowConnect

              spark.dataSource.register(GmailDataSource)

        - Merged single-file deployment (SDP): ``_lakeflow_connect_cls`` is left
          ``None`` and the connector is taken from the module-level
          ``LakeflowConnectImpl`` placeholder, which the merge script substitutes
          with the actual implementation class.
        """

        # Per-source subclasses set this. Left ``None`` on the base so the merged
        # single-file path falls back to the ``LakeflowConnectImpl`` placeholder.
        _lakeflow_connect_cls = None

        # Spark format name. Defaults to "lakeflow_connect" because Unity Catalog
        # connection-option injection looks for that exact string. A per-source
        # subclass may override this with its source name once it no longer relies
        # on UC injection (see the commented override in each source's __init__.py).
        _format_name = "lakeflow_connect"

        def __init__(self, options):
            self.options = options
            table = options.get(TABLE_NAME)
            # Catch typos against the framework's reserved virtual-table namespace
            # early — falling through to the connector with an unknown
            # `_community_*` name yields a confusing per-connector error.
            if table and table.startswith("_community_") and table not in VIRTUAL_TABLES:
                raise ValueError(
                    f"unknown framework virtual table '{table}'. Valid framework "
                    f"virtual tables are: {', '.join(VIRTUAL_TABLES)}. "
                    f"For a regular source table, use a name that does not start "
                    f"with '_community_'."
                )
            # Per-source subclasses bind the implementation via _lakeflow_connect_cls.
            # The merged single-file path leaves it None and relies on the
            # LakeflowConnectImpl placeholder (substituted by the merge script).
            connect_cls = type(self)._lakeflow_connect_cls or LakeflowConnectImpl
            self.lakeflow_connect = connect_cls(options)  # pylint: disable=abstract-class-instantiated

        @classmethod
        def name(cls):
            return cls._format_name

        def schema(self):
            table = self.options[TABLE_NAME]
            if table == METADATA_TABLE:
                return StructType(
                    [
                        StructField(TABLE_NAME, StringType(), False),
                        StructField("primary_keys", ArrayType(StringType()), True),
                        StructField("cursor_field", StringType(), True),
                        StructField("ingestion_type", StringType(), True),
                    ]
                )
            if table == NAMESPACES_TABLE:
                return StructType(
                    [
                        StructField("namespace", ArrayType(StringType()), False),
                    ]
                )
            if table == TABLES_TABLE:
                return StructType(
                    [
                        StructField("namespace", ArrayType(StringType()), False),
                        StructField(TABLE_NAME, StringType(), False),
                    ]
                )
            return self.lakeflow_connect.get_table_schema(table, self.options)

        def reader(self, schema: StructType):
            return LakeflowBatchReader(self.options, schema, self.lakeflow_connect)

        def streamReader(self, schema: StructType):
            # Use the partitioned DataSourceStreamReader when the connector
            # implements SupportsPartitionedStream and the table opts in.
            # Otherwise, delegate to super() which raises PySparkNotImplementedError,
            # causing Spark to fall back to simpleStreamReader().
            if isinstance(self.lakeflow_connect, SupportsPartitionedStream):
                table = self.options[TABLE_NAME]
                if self.lakeflow_connect.is_partitioned(table):
                    return LakeflowPartitionedStreamReader(self.options, schema, self.lakeflow_connect)
            return super().streamReader(schema)

        def simpleStreamReader(self, schema: StructType):
            return LakeflowStreamReader(self.options, schema, self.lakeflow_connect)


    spark.dataSource.register(LakeflowSource)
